//! Tests for the committed Round 9 example golden.
//!
//! The golden days reading of the standing example meet is
//! regenerated by the days command itself, and these pins
//! fail if the example, the golden, or the reading drifts
//! away from the hand computed days of the standing meet, and
//! the reconciliation pins read the meet report and the reign
//! reading over the same file and fail when the days reading
//! disagrees with either over the closes and the counts.

use std::fs;
use std::path::PathBuf;

use paceghost::cli::dispatch;
use paceghost::meet::{load_meet_file, meet_days, meet_reign, meet_report};
use paceghost::pytext::PText;

fn reader(bytes: &[u8]) -> Option<String> {
    let path = String::from_utf8_lossy(bytes).into_owned();
    let data = std::fs::read(path).ok()?;
    String::from_utf8(data).ok()
}

fn examples_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("examples")
}

#[test]
fn test_the_example_days_match_the_golden_bytes() {
    let examples = examples_dir();
    let (meet, defects) = load_meet_file(&examples.join("meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the example meet loads");
    let lines = meet_days(&meet).expect("the example days read");
    let golden =
        fs::read_to_string(examples.join("meet-days-golden.txt")).expect("the golden file reads");
    let golden_lines: Vec<&str> = golden.lines().collect();
    assert_eq!(lines, golden_lines);
    assert!(golden.ends_with('\n'));
}

#[test]
fn test_the_days_command_prints_the_golden_days() {
    let examples = examples_dir();
    let golden =
        fs::read_to_string(examples.join("meet-days-golden.txt")).expect("the golden file reads");
    let golden_lines: Vec<String> = golden.lines().map(str::to_string).collect();
    let argv: Vec<PText> = vec![
        PText::from_text("days"),
        PText::from_text(examples.join("meet.json").to_str().unwrap()),
    ];
    let outcome = dispatch(&argv, &reader);
    assert_eq!(outcome.code, 0);
    assert_eq!(outcome.stdout, golden_lines);
    assert!(outcome.stderr.is_empty());
}

#[test]
fn test_the_example_days_close_on_the_hand_counts() {
    let examples = examples_dir();
    let (meet, defects) = load_meet_file(&examples.join("meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the example meet loads");
    let lines = meet_days(&meet).expect("the example days read");
    // The hand counts of the standing meet, computed from the
    // one walk. The first day walks eight marks and three
    // handovers and closes with night fork at 840, the second
    // walks five marks and one handover and closes with dawn
    // fork at 675, and the third walks three marks and no
    // handover and closes with dawn fork at 560.
    assert_eq!(
        lines[1],
        "day, the first day, marks 8, handovers 3, record at the close held by night fork at a projection of 840"
    );
    assert_eq!(
        lines[2],
        "day, the second day, marks 5, handovers 1, record at the close held by dawn fork at a projection of 675"
    );
    assert_eq!(
        lines[3],
        "day, the third day, marks 3, handovers 0, record at the close held by dawn fork at a projection of 560"
    );
    assert_eq!(
        lines.last().map(String::as_str),
        Some("days counts, days 3, marks walked 16, handovers 4")
    );
}

#[test]
fn test_the_example_day_closes_agree_with_the_meet_report() {
    let examples = examples_dir();
    let (meet, defects) = load_meet_file(&examples.join("meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the example meet loads");
    let lines = meet_days(&meet).expect("the example days read");
    let report = meet_report(&meet).expect("the report reads");
    let ordinals = ["first", "second", "third"];
    for (index, ordinal) in ordinals.iter().enumerate() {
        let close = report
            .iter()
            .find(|line| line.starts_with(&format!("close of the {} day, ", ordinal)))
            .expect("the report closes the day");
        let rest = close
            .strip_prefix(&format!("close of the {} day, record held by ", ordinal))
            .expect("the report close names its holder");
        assert_eq!(
            lines[index + 1]
                .rsplit(", record at the close held by ")
                .next(),
            Some(rest),
            "the day line close names the report close for the {} day",
            ordinal
        );
    }
    let finish = report
        .iter()
        .find(|line| line.starts_with("finish, record held by "))
        .expect("the report finish line stands");
    let finish_rest = finish
        .strip_prefix("finish, record held by ")
        .expect("the finish line names its holder");
    assert_eq!(
        lines[3].rsplit(", record at the close held by ").next(),
        Some(finish_rest),
        "the last day line close names the report finish"
    );
}

#[test]
fn test_the_example_handovers_agree_with_the_reign_spells() {
    let examples = examples_dir();
    let (meet, defects) = load_meet_file(&examples.join("meet.json"));
    assert_eq!(defects, Vec::<String>::new());
    let meet = meet.expect("the example meet loads");
    let lines = meet_days(&meet).expect("the example days read");
    let reign = meet_reign(&meet).expect("the reign reads");
    let reign_counts = reign.last().expect("the reign counts line stands");
    let spells: i64 = reign_counts
        .split("spells ")
        .nth(1)
        .expect("the reign counts line names the spells")
        .split(',')
        .next()
        .expect("the spells count stands")
        .parse()
        .expect("the spells count is a whole number");
    let walked: i64 = reign_counts
        .split("marks walked ")
        .nth(1)
        .expect("the reign counts line names the marks")
        .split(',')
        .next()
        .expect("the marks count stands")
        .parse()
        .expect("the marks count is a whole number");
    let counts = lines.last().expect("the counts line stands");
    assert!(counts.contains(&format!("marks walked {}", walked)));
    assert!(counts.ends_with(&format!("handovers {}", spells - 1)));
    assert_eq!(spells, 5);
    assert_eq!(walked, 16);
}
